// Definition for a binary tree node.
// class TreeNode {
//     int val;
//     TreeNode left;
//     TreeNode right;
//     TreeNode(int x) { val = x; }
// }
public int maxPathSum(TreeNode root) {
    if (root == null) {
        return 0;
    }
    int peakHere = root.val
        + Math.max(down(root.left), 0)
        + Math.max(down(root.right), 0);
    int best = peakHere;
    if (root.left != null) best = Math.max(best, maxPathSum(root.left));
    if (root.right != null) best = Math.max(best, maxPathSum(root.right));
    return best;
}

// Best straight downward path starting at node (0 if all negative).
private int down(TreeNode node) {
    if (node == null) {
        return 0;
    }
    return node.val + Math.max(0, Math.max(down(node.left), down(node.right)));
}

