# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
def maxPathSum(self, root: 'TreeNode') -> int:
    def down(node: 'TreeNode') -> int:
        if node is None:
            return 0
        return node.val + max(0, down(node.left), down(node.right))

    def best_with_peaks(node: 'TreeNode') -> int:
        if node is None:
            return float('-inf')
        peak_here = node.val + max(down(node.left), 0) + max(down(node.right), 0)
        return max(peak_here, best_with_peaks(node.left), best_with_peaks(node.right))

    return best_with_peaks(root)

