// Definition for a binary tree node.
// class TreeNode {
//     int val;
//     TreeNode left;
//     TreeNode right;
//     TreeNode(int x) { val = x; }
// }
private int best;

public int maxPathSum(TreeNode root) {
    best = Integer.MIN_VALUE;
    gain(root);
    return best;
}

// Returns the best single-branch downward gain from node.
private int gain(TreeNode node) {
    if (node == null) {
        return 0;
    }
    int leftGain = Math.max(gain(node.left), 0);
    int rightGain = Math.max(gain(node.right), 0);
    best = Math.max(best, node.val + leftGain + rightGain); // split through node
    return node.val + Math.max(leftGain, rightGain);        // one branch upward
}

